// Mark habit complete
app.post('/api/habits/:id/complete', async (req, res) => {
  try {
    const user = await getUserFromToken(req.headers.authorization);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ error: 'Date is required' });
    }

    const completionDate = new Date(date);
    const today = new Date();
    today.setUTCHours(0, 0, 0, 0);

    if (completionDate > today) {
      return res.status(400).json({ error: 'Cannot mark future dates as complete' });
    }

    const habitRes = await pbFetch(`/collections/habits/records/${req.params.id}`, {
      headers: { Authorization: req.headers.authorization },
    });

    if (!habitRes.ok) {
      return res.status(habitRes.status).json(await habitRes.json());
    }

    const habit = await habitRes.json();

    if (habit.user_id !== user.id) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const existingRes = await pbFetch(
      `/collections/completions/records?filter=(user_id='${user.id}' %26%26 habit_id='${req.params.id}' %26%26 date='${date}')`,
      { headers: { Authorization: req.headers.authorization } }
    );

    if (existingRes.ok) {
      const existing = await existingRes.json();
      if (existing.items.length > 0) {
        return res.status(200).json({ message: 'Already marked complete' });
      }
    }

    const response = await pbFetch('/collections/completions/records', {
      method: 'POST',
      headers: { Authorization: req.headers.authorization },
      body: JSON.stringify({
        user_id: user.id,
        habit_id: req.params.id,
        date,
      }),
    });

    if (!response.ok) {
      return res.status(response.status).json(await response.json());
    }

    const completion = await response.json();
    res.status(201).json(completion);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Unmark habit complete
app.delete('/api/habits/:id/complete', async (req, res) => {
  try {
    const user = await getUserFromToken(req.headers.authorization);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ error: 'Date is required' });
    }

    const habitRes = await pbFetch(`/collections/habits/records/${req.params.id}`, {
      headers: { Authorization: req.headers.authorization },
    });

    if (!habitRes.ok) {
      return res.status(habitRes.status).json(await habitRes.json());
    }

    const habit = await habitRes.json();

    if (habit.user_id !== user.id) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const existingRes = await pbFetch(
      `/collections/completions/records?filter=(user_id='${user.id}' %26%26 habit_id='${req.params.id}' %26%26 date='${date}')`,
      { headers: { Authorization: req.headers.authorization } }
    );

    if (!existingRes.ok) {
      return res.status(204).send();
    }

    const existing = await existingRes.json();

    if (existing.items.length === 0) {
      return res.status(204).send();
    }

    const deleteRes = await pbFetch(`/collections/completions/records/${existing.items[0].id}`, {
      method: 'DELETE',
      headers: { Authorization: req.headers.authorization },
    });

    if (!deleteRes.ok) {
      return res.status(deleteRes.status).json(await deleteRes.json());
    }

    res.status(204).send();
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

