// Get single habit
app.get('/api/habits/:id', async (req, res) => {
  try {
    const user = await getUserFromToken(req.headers.authorization);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const habitRes = await pbFetch(`/collections/habits/records/${req.params.id}`, {
      headers: { Authorization: req.headers.authorization },
    });

    if (!habitRes.ok) {
      return res.status(habitRes.status).json(await habitRes.json());
    }

    const habit = await habitRes.json();

    if (habit.user_id !== user.id) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const completionsRes = await pbFetch(`/collections/completions/records?filter=(habit_id='${habit.id}')&perPage=5000`, {
      headers: { Authorization: req.headers.authorization },
    });

    const completionsData = completionsRes.ok ? await completionsRes.json() : { items: [] };
    const streaks = calculateStreaks(completionsData.items, habit.id);

    res.json({
      id: habit.id,
      name: habit.name,
      description: habit.description,
      color: habit.color,
      created: habit.created,
      ...streaks,
      completions: completionsData.items.map(c => ({ date: c.date, id: c.id })),
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Update habit
app.patch('/api/habits/:id', async (req, res) => {
  try {
    const user = await getUserFromToken(req.headers.authorization);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const habitRes = await pbFetch(`/collections/habits/records/${req.params.id}`, {
      headers: { Authorization: req.headers.authorization },
    });

    if (!habitRes.ok) {
      return res.status(habitRes.status).json(await habitRes.json());
    }

    const habit = await habitRes.json();

    if (habit.user_id !== user.id) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const updateData = {};
    if (req.body.name !== undefined) updateData.name = req.body.name;
    if (req.body.color !== undefined) updateData.color = req.body.color;
    if (req.body.description !== undefined) updateData.description = req.body.description;

    const response = await pbFetch(`/collections/habits/records/${req.params.id}`, {
      method: 'PATCH',
      headers: { Authorization: req.headers.authorization },
      body: JSON.stringify(updateData),
    });

    if (!response.ok) {
      return res.status(response.status).json(await response.json());
    }

    const updated = await response.json();

    const completionsRes = await pbFetch(`/collections/completions/records?filter=(habit_id='${updated.id}')&perPage=5000`, {
      headers: { Authorization: req.headers.authorization },
    });

    const completionsData = completionsRes.ok ? await completionsRes.json() : { items: [] };
    const streaks = calculateStreaks(completionsData.items, updated.id);

    res.json({
      id: updated.id,
      name: updated.name,
      description: updated.description,
      color: updated.color,
      created: updated.created,
      ...streaks,
    });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

