const express = require('express');
const path = require('path');
const fetch = require('node-fetch');

const app = express();
const PORT = process.env.APP_PUBLIC_PORT || 4173;
const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';

app.use(express.json());

// Helper to call PocketBase API
async function pbFetch(path, options = {}) {
  const url = `${BACKEND_URL}/api${path}`;
  const response = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  return response;
}

// Helper to verify auth token and get user
async function getUserFromToken(authHeader) {
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }
  const token = authHeader.substring(7);

  try {
    const response = await pbFetch('/collections/users/auth-refresh', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
    });

    if (!response.ok) return null;
    const data = await response.json();
    return data.record;
  } catch (error) {
    return null;
  }
}

// Calculate streaks for a habit
function calculateStreaks(completions, habitId) {
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);

  const dates = completions
    .filter(c => c.habit_id === habitId)
    .map(c => new Date(c.date))
    .sort((a, b) => b - a);

  if (dates.length === 0) {
    return { current_streak: 0, longest_streak: 0, completed_today: false };
  }

  const completedToday = dates.some(d => d.getTime() === today.getTime());

  let currentStreak = 0;
  let checkDate = new Date(today);

  for (const date of dates) {
    if (date.getTime() === checkDate.getTime()) {
      currentStreak++;
      checkDate.setUTCDate(checkDate.getUTCDate() - 1);
    } else if (date.getTime() < checkDate.getTime()) {
      break;
    }
  }

  let longestStreak = 0;
  let tempStreak = 1;

  for (let i = 1; i < dates.length; i++) {
    const diff = Math.round((dates[i - 1] - dates[i]) / (1000 * 60 * 60 * 24));
    if (diff === 1) {
      tempStreak++;
    } else {
      longestStreak = Math.max(longestStreak, tempStreak);
      tempStreak = 1;
    }
  }
  longestStreak = Math.max(longestStreak, tempStreak);

  return { current_streak: currentStreak, longest_streak: longestStreak, completed_today: completedToday };
}

// Health check
app.get('/api/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

// Login
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const response = await pbFetch('/collections/users/auth-with-password', {
      method: 'POST',
      body: JSON.stringify({ identity: email, password }),
    });

    if (!response.ok) {
      const error = await response.json();
      return res.status(response.status).json(error);
    }

    const data = await response.json();
    res.json({ access_token: data.token, user: data.record });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get all habits
app.get('/api/habits', async (req, res) => {
  try {
    const user = await getUserFromToken(req.headers.authorization);
    if (!user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    const habitsRes = await pbFetch(`/collections/habits/records?filter=(user_id='${user.id}' %26%26 deleted=false)`, {
      headers: { Authorization: req.headers.authorization },
    });

    if (!habitsRes.ok) {
      return res.status(habitsRes.status).json(await habitsRes.json());
    }

    const habitsData = await habitsRes.json();

    const completionsRes = await pbFetch(`/collections/completions/records?filter=(user_id='${user.id}')&perPage=5000`, {
      headers: { Authorization: req.headers.authorization },
    });

    const completionsData = completionsRes.ok ? await completionsRes.json() : { items: [] };

    const habits = habitsData.items.map(habit => {
      const streaks = calculateStreaks(completionsData.items, habit.id);
      return {
        id: habit.id,
        name: habit.name,
        description: habit.description,
        color: habit.color,
        created: habit.created,
        ...streaks,
      };
    });

    res.json(habits);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

