const fetch = require('node-fetch');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = process.env.POCKETBASE_ADMIN_EMAIL || 'admin@ethara.local';
const ADMIN_PASSWORD = process.env.POCKETBASE_ADMIN_PASSWORD || 'admin-password-2026';

async function pbAdminAuth() {
  const response = await fetch(`${BACKEND_URL}/api/admins/auth-with-password`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      identity: ADMIN_EMAIL,
      password: ADMIN_PASSWORD,
    }),
  });

  if (!response.ok) {
    if (response.status === 400) {
      console.log('Admin not found, creating admin...');
      const createRes = await fetch(`${BACKEND_URL}/api/admins`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: ADMIN_EMAIL,
          password: ADMIN_PASSWORD,
          passwordConfirm: ADMIN_PASSWORD,
        }),
      });

      if (!createRes.ok) {
        const error = await createRes.text();
        throw new Error(`Failed to create admin: ${error}`);
      }

      return pbAdminAuth();
    }
    throw new Error(`Failed to authenticate: ${await response.text()}`);
  }

  const data = await response.json();
  return data.token;
}

async function createCollection(token, schema) {
  const response = await fetch(`${BACKEND_URL}/api/collections`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
    },
    body: JSON.stringify(schema),
  });

  if (!response.ok) {
    const error = await response.text();
    if (error.includes('already exists')) {
      console.log(`Collection ${schema.name} already exists`);
      return null;
    }
    throw new Error(`Failed to create collection ${schema.name}: ${error}`);
  }

  return response.json();
}

async function getCollection(token, name) {
  const response = await fetch(`${BACKEND_URL}/api/collections/${name}`, {
    headers: { 'Authorization': `Bearer ${token}` },
  });

  if (!response.ok) {
    return null;
  }

  return response.json();
}

