        {
          name: 'date',
          type: 'text',
          required: true,
          options: {
            min: 10,
            max: 10,
            pattern: '^\\d{4}-\\d{2}-\\d{2}$',
          },
        },
      ],
      indexes: [
        'CREATE UNIQUE INDEX idx_completion ON completions (user_id, habit_id, date)',
      ],
      listRule: '@request.auth.id != "" && user_id = @request.auth.id',
      viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
      createRule: '@request.auth.id != ""',
      updateRule: null,
      deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
    });
    console.log('Completions collection created');
  } else {
    console.log('Completions collection already exists, updating...');
    await updateCollection(token, completionsCollection.id, {
      schema: completionsCollection.schema,
      indexes: [
        'CREATE UNIQUE INDEX IF NOT EXISTS idx_completion ON completions (user_id, habit_id, date)',
      ],
      listRule: '@request.auth.id != "" && user_id = @request.auth.id',
      viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
