const fetch = require('node-fetch');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const DEMO_EMAIL = 'demo@ethara.ai';
const DEMO_PASSWORD = 'deku-demo-pw-2026';

function formatDate(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function getDateDaysAgo(days) {
  const date = new Date();
  date.setUTCDate(date.getUTCDate() - days);
  date.setUTCHours(0, 0, 0, 0);
  return date;
}

async function pbFetch(path, options = {}) {
  const url = `${BACKEND_URL}/api${path}`;
  const response = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  return response;
}

async function createUser() {
  console.log('Creating demo user...');

  const response = await pbFetch('/collections/users/records', {
    method: 'POST',
    body: JSON.stringify({
      email: DEMO_EMAIL,
      password: DEMO_PASSWORD,
      passwordConfirm: DEMO_PASSWORD,
      emailVisibility: true,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    if (error.includes('already exists')) {
      console.log('Demo user already exists');

      const authResponse = await pbFetch('/collections/users/auth-with-password', {
        method: 'POST',
        body: JSON.stringify({
          identity: DEMO_EMAIL,
          password: DEMO_PASSWORD,
        }),
      });

      if (!authResponse.ok) {
        throw new Error(`Failed to authenticate: ${await authResponse.text()}`);
      }

      const authData = await authResponse.json();
      return authData.record;
    }
    throw new Error(`Failed to create user: ${error}`);
  }

  const user = await response.json();
  console.log('Demo user created');
  return user;
}

async function loginUser() {
  const response = await pbFetch('/collections/users/auth-with-password', {
    method: 'POST',
    body: JSON.stringify({
      identity: DEMO_EMAIL,
      password: DEMO_PASSWORD,
    }),
  });

  if (!response.ok) {
    throw new Error(`Failed to login: ${await response.text()}`);
  }

  const data = await response.json();
  return { user: data.record, token: data.token };
}

async function createHabit(userId, token, name, color, description = '') {
  const response = await pbFetch('/collections/habits/records', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      user_id: userId,
      name,
      color,
      description,
      deleted: false,
    }),
  });

  if (!response.ok) {
    const error = await response.text();
    if (error.includes('already exists')) {
      console.log(`Habit "${name}" already exists, fetching...`);

      const listResponse = await pbFetch(
        `/collections/habits/records?filter=(user_id='${userId}' %26%26 name='${name}')`,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!listResponse.ok) {
        throw new Error(`Failed to fetch habit: ${await listResponse.text()}`);
      }

      const listData = await listResponse.json();
      if (listData.items.length > 0) {
        return listData.items[0];
      }
    }
    throw new Error(`Failed to create habit: ${error}`);
  }

  return response.json();
}

async function createCompletion(userId, token, habitId, date) {
  const dateStr = formatDate(date);

  const existingResponse = await pbFetch(
    `/collections/completions/records?filter=(user_id='${userId}' %26%26 habit_id='${habitId}' %26%26 date='${dateStr}')`,
    { headers: { Authorization: `Bearer ${token}` } }
  );

  if (existingResponse.ok) {
    const existing = await existingResponse.json();
    if (existing.items.length > 0) {
      console.log(`Completion for ${dateStr} already exists`);
      return existing.items[0];
    }
  }

  const response = await pbFetch('/collections/completions/records', {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: JSON.stringify({
      user_id: userId,
      habit_id: habitId,
      date: dateStr,
    }),
  });

  if (!response.ok) {
    throw new Error(`Failed to create completion: ${await response.text()}`);
  }

  return response.json();
}

async function seed() {
  console.log('Starting seed process...');

  await createUser();
  const { user, token } = await loginUser();
  console.log(`Logged in as ${user.email}`);

  console.log('\nCreating habits...');

  const meditateHabit = await createHabit(
    user.id,
    token,
    'Meditate',
    'indigo',
    'Daily meditation practice'
  );
  console.log('Created: Meditate');

  const readHabit = await createHabit(
    user.id,
    token,
    'Read 20 minutes',
    'teal',
    'Read for at least 20 minutes'
  );
  console.log('Created: Read 20 minutes');

  const noSodaHabit = await createHabit(
    user.id,
    token,
    'No soda',
    'amber',
    'Avoid drinking soda'
  );
  console.log('Created: No soda');

  console.log('\nCreating completions...');

  // Meditate: current_streak = 5 (today and 4 preceding days)
  console.log('Seeding Meditate habit with 5-day streak...');
  for (let i = 0; i < 5; i++) {
    const date = getDateDaysAgo(i);
    await createCompletion(user.id, token, meditateHabit.id, date);
    console.log(`  - Completion for ${formatDate(date)}`);
  }

  // Read 20 minutes: current_streak = 0, longest_streak >= 3
  // Create a 3-day streak 7-9 days ago, and nothing today
  console.log('Seeding Read 20 minutes habit with past 3-day streak...');
  for (let i = 7; i <= 9; i++) {
    const date = getDateDaysAgo(i);
    await createCompletion(user.id, token, readHabit.id, date);
    console.log(`  - Completion for ${formatDate(date)}`);
  }

  // No soda: current_streak = 1 (today only, gap yesterday)
  console.log('Seeding No soda habit with 1-day streak...');
  const today = getDateDaysAgo(0);
  await createCompletion(user.id, token, noSodaHabit.id, today);
  console.log(`  - Completion for ${formatDate(today)}`);

  console.log('\nSeed data created successfully!');
  console.log(`\nDemo account credentials:`);
  console.log(`Email: ${DEMO_EMAIL}`);
  console.log(`Password: ${DEMO_PASSWORD}`);
}

seed().catch(console.error);

