const PocketBase = require('pocketbase');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

async function createCollections() {
  console.log('Attempting to create PocketBase collections...');
  console.log('\nNOTE: This script requires PocketBase to have an admin user.');
  console.log('If this is your first time running, please:');
  console.log('1. Open http://pocketbase:8090/_/ in your browser');
  console.log('2. Create an admin account');
  console.log('3. Then run this script with POCKETBASE_ADMIN_EMAIL and POCKETBASE_ADMIN_PASSWORD env vars\n');

  const adminEmail = process.env.POCKETBASE_ADMIN_EMAIL;
  const adminPassword = process.env.POCKETBASE_ADMIN_PASSWORD;

  if (!adminEmail || !adminPassword) {
    console.log('Skipping collection creation - no admin credentials provided');
    console.log('Set POCKETBASE_ADMIN_EMAIL and POCKETBASE_ADMIN_PASSWORD to enable auto-setup\n');
    process.exit(0);
  }

  try {
    // Authenticate as admin
    await pb.admins.authWithPassword(adminEmail, adminPassword);
    console.log('Authenticated as admin');

    // Note: PocketBase JS SDK doesn't expose collection creation API
    // Collections should be created through the admin UI or via direct API calls
    console.log('\nFor now, please create collections through the PocketBase admin UI:');
    console.log('1. Go to http://pocketbase:8090/_/#/collections');
    console.log('2. Create the following collections with the schemas defined in the docs\n');
  } catch (error) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

createCollections();

