import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '../api/client';
import { Link } from 'react-router-dom';

export function Dashboard() {
  const { data: dashboard, isLoading, error } = useQuery({
    queryKey: ['dashboard'],
    queryFn: () => apiClient.getDashboard(),
  });

  if (isLoading) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            <div className="h-24 bg-gray-200 rounded"></div>
            <div className="h-24 bg-gray-200 rounded"></div>
            <div className="h-24 bg-gray-200 rounded"></div>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
          Error loading dashboard: {error instanceof Error ? error.message : 'Unknown error'}
        </div>
      </div>
    );
  }

  if (!dashboard) {
    return null;
  }

  const getColorClass = (color: string) => {
    const colors: Record<string, string> = {
      indigo: 'bg-[var(--color-indigo)]',
      teal: 'bg-[var(--color-teal)]',
      amber: 'bg-[var(--color-amber)]',
      rose: 'bg-[var(--color-rose)]',
      slate: 'bg-[var(--color-slate)]',
      forest: 'bg-[var(--color-forest)]',
    };
    return colors[color] || colors.indigo;
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <h1 className="text-[28px] font-medium leading-[1.25] mb-8">Dashboard</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
        <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)]">
          <div className="text-[var(--color-text-muted)] text-sm mb-1">Total Habits</div>
          <div className="text-[28px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
            {dashboard.total_habits}
          </div>
        </div>

        <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)]">
          <div className="text-[var(--color-text-muted)] text-sm mb-1">Total Completions</div>
          <div className="text-[28px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
            {dashboard.total_completions}
          </div>
        </div>

        <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)]">
          <div className="text-[var(--color-text-muted)] text-sm mb-1">Active Streaks</div>
          <div className="text-[28px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
            {dashboard.habits_with_active_streak}
          </div>
        </div>
      </div>

      {dashboard.habits.length === 0 ? (
        <div className="bg-[var(--color-surface)] rounded-xl p-12 border border-[var(--color-border)] text-center">
          <p className="text-[var(--color-text-muted)] mb-4">No habits yet. Start building your routine!</p>
          <Link
            to="/habits"
            className="inline-block bg-[var(--color-primary)] text-white px-6 py-2 rounded-lg hover:bg-[var(--color-primary-hover)] transition-colors"
          >
            Add Your First Habit
          </Link>
        </div>
      ) : (
        <div className="bg-[var(--color-surface)] rounded-xl border border-[var(--color-border)] overflow-hidden">
          <table className="w-full">
            <thead className="bg-[var(--color-bg)] border-b border-[var(--color-border)] sticky top-0">
              <tr>
                <th className="text-left px-4 py-3 text-sm font-medium">Habit</th>
                <th className="text-left px-4 py-3 text-sm font-medium">Current Streak</th>
                <th className="text-left px-4 py-3 text-sm font-medium">Longest Streak</th>
                <th className="text-left px-4 py-3 text-sm font-medium">Today</th>
              </tr>
            </thead>
            <tbody>
              {dashboard.habits.map((habit) => (
                <tr key={habit.id} className="border-b border-[var(--color-border)] last:border-0">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className={`w-3 h-3 rounded-full ${getColorClass(habit.color)}`}></div>
                      <Link
                        to={`/habits/${habit.id}`}
                        className="hover:text-[var(--color-primary)] transition-colors"
                      >
                        {habit.name}
                      </Link>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-mono" style={{ fontVariantNumeric: 'tabular-nums' }}>
                      {habit.current_streak}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-mono" style={{ fontVariantNumeric: 'tabular-nums' }}>
                      {habit.longest_streak}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    {habit.completed_today ? (
                      <span className="text-[var(--color-success)]">✓</span>
                    ) : (
                      <span className="text-[var(--color-text-muted)]">—</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

