import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiClient } from '../api/client';
import type { HabitColor } from '../types';

const COLORS: { value: HabitColor; label: string }[] = [
  { value: 'indigo', label: 'Indigo' },
  { value: 'teal', label: 'Teal' },
  { value: 'amber', label: 'Amber' },
  { value: 'rose', label: 'Rose' },
  { value: 'slate', label: 'Slate' },
  { value: 'forest', label: 'Forest' },
];

export function Habits() {
  const [isAdding, setIsAdding] = useState(false);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [color, setColor] = useState<HabitColor>('indigo');
  const [error, setError] = useState('');

  const queryClient = useQueryClient();

  const { data: habits, isLoading } = useQuery({
    queryKey: ['habits'],
    queryFn: () => apiClient.getHabits(),
  });

  const createMutation = useMutation({
    mutationFn: (data: { name: string; color: HabitColor; description?: string }) =>
      apiClient.createHabit(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      setIsAdding(false);
      setName('');
      setDescription('');
      setColor('indigo');
      setError('');
    },
    onError: (err: Error) => {
      setError(err.message);
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (id: string) => apiClient.deleteHabit(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    createMutation.mutate({ name, color, description: description || undefined });
  };

  const handleDelete = (id: string, name: string) => {
    if (window.confirm(`Delete habit "${name}"? This cannot be undone.`)) {
      deleteMutation.mutate(id);
    }
  };

  const getColorClass = (color: string) => {
    const colors: Record<string, string> = {
      indigo: 'bg-[var(--color-indigo)]',
      teal: 'bg-[var(--color-teal)]',
      amber: 'bg-[var(--color-amber)]',
      rose: 'bg-[var(--color-rose)]',
      slate: 'bg-[var(--color-slate)]',
      forest: 'bg-[var(--color-forest)]',
    };
    return colors[color] || colors.indigo;
  };

  if (isLoading) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-4"></div>
          <div className="h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-[28px] font-medium leading-[1.25]">Habits</h1>
        {!isAdding && (
          <button
            onClick={() => setIsAdding(true)}
            className="bg-[var(--color-primary)] text-white px-4 py-2 rounded-lg hover:bg-[var(--color-primary-hover)] transition-colors"
          >
            Add Habit
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)] mb-6">
          <h2 className="text-[18px] font-medium mb-4">New Habit</h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="name" className="block text-sm font-medium mb-1">
                Name *
              </label>
              <input
                id="name"
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                maxLength={80}
                className="w-full px-3 py-2 border border-[var(--color-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)] bg-[var(--color-surface)]"
              />
            </div>

            <div>
              <label htmlFor="description" className="block text-sm font-medium mb-1">
                Description
              </label>
              <textarea
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                maxLength={200}
                rows={3}
                className="w-full px-3 py-2 border border-[var(--color-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)] bg-[var(--color-surface)]"
              />
            </div>

            <div>
              <label htmlFor="color" className="block text-sm font-medium mb-1">
                Color *
              </label>
              <select
                id="color"
                value={color}
                onChange={(e) => setColor(e.target.value as HabitColor)}
                required
                className="w-full px-3 py-2 border border-[var(--color-border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)] bg-[var(--color-surface)]"
              >
                {COLORS.map((c) => (
                  <option key={c.value} value={c.value}>
                    {c.label}
                  </option>
                ))}
              </select>
            </div>

            {error && (
              <div className="text-[var(--color-danger)] text-sm bg-red-50 dark:bg-red-900/10 p-3 rounded-lg">
                {error}
              </div>
            )}

            <div className="flex gap-2">
              <button
                type="submit"
                disabled={createMutation.isPending}
                className="bg-[var(--color-primary)] text-white px-4 py-2 rounded-lg hover:bg-[var(--color-primary-hover)] transition-colors disabled:opacity-50"
              >
                {createMutation.isPending ? 'Creating...' : 'Create Habit'}
              </button>
              <button
                type="button"
                onClick={() => {
                  setIsAdding(false);
                  setError('');
                }}
                className="px-4 py-2 border border-[var(--color-border)] rounded-lg hover:bg-[var(--color-bg)] transition-colors"
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {habits && habits.length === 0 ? (
        <div className="bg-[var(--color-surface)] rounded-xl p-12 border border-[var(--color-border)] text-center">
          <p className="text-[var(--color-text-muted)] mb-4">No habits yet. Add your first habit to get started!</p>
        </div>
      ) : (
        <div className="bg-[var(--color-surface)] rounded-xl border border-[var(--color-border)] overflow-hidden">
          <table className="w-full">
            <thead className="bg-[var(--color-bg)] border-b border-[var(--color-border)]">
              <tr>
                <th className="text-left px-4 py-3 text-sm font-medium">Habit</th>
                <th className="text-left px-4 py-3 text-sm font-medium">Current Streak</th>
                <th className="text-left px-4 py-3 text-sm font-medium">Longest Streak</th>
                <th className="text-right px-4 py-3 text-sm font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {habits?.map((habit) => (
                <tr key={habit.id} className="border-b border-[var(--color-border)] last:border-0">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <div className={`w-3 h-3 rounded-full ${getColorClass(habit.color)}`}></div>
                      <div>
                        <div>{habit.name}</div>
                        {habit.description && (
                          <div className="text-sm text-[var(--color-text-muted)]">{habit.description}</div>
                        )}
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-mono" style={{ fontVariantNumeric: 'tabular-nums' }}>
                      {habit.current_streak}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <span className="font-mono" style={{ fontVariantNumeric: 'tabular-nums' }}>
                      {habit.longest_streak}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <button
                      onClick={() => handleDelete(habit.id, habit.name)}
                      disabled={deleteMutation.isPending}
                      className="text-[var(--color-danger)] hover:underline disabled:opacity-50"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

