import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tantml:query';
import { apiClient } from '../api/client';

export function HabitDetail() {
  const { id } = useParams<{ id: string }>();
  const queryClient = useQueryClient();

  const { data: habit, isLoading } = useQuery({
    queryKey: ['habit', id],
    queryFn: () => apiClient.getHabit(id!),
    enabled: !!id,
  });

  const toggleMutation = useMutation({
    mutationFn: async ({ date, isCompleted }: { date: string; isCompleted: boolean }) => {
      if (isCompleted) {
        await apiClient.unmarkComplete(id!, date);
      } else {
        await apiClient.markComplete(id!, date);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habit', id] });
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });

  const handleToggleToday = () => {
    const today = new Date().toISOString().split('T')[0];
    toggleMutation.mutate({ date: today, isCompleted: habit?.completed_today || false });
  };

  if (isLoading) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
          <div className="h-64 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  if (!habit) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="text-[var(--color-danger)]">Habit not found</div>
      </div>
    );
  }

  const getColorClass = (color: string) => {
    const colors: Record<string, string> = {
      indigo: 'bg-[var(--color-indigo)]',
      teal: 'bg-[var(--color-teal)]',
      amber: 'bg-[var(--color-amber)]',
      rose: 'bg-[var(--color-rose)]',
      slate: 'bg-[var(--color-slate)]',
      forest: 'bg-[var(--color-forest)]',
    };
    return colors[color] || colors.indigo;
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <div className="mb-4">
        <Link to="/habits" className="text-[var(--color-primary)] hover:underline">
          ← Back to Habits
        </Link>
      </div>

      <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)] mb-6">
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className={`w-4 h-4 rounded-full ${getColorClass(habit.color)}`}></div>
            <h1 className="text-[28px] font-medium leading-[1.25]">{habit.name}</h1>
          </div>
        </div>

        {habit.description && (
          <p className="text-[var(--color-text-muted)] mb-6">{habit.description}</p>
        )}

        <div className="grid grid-cols-3 gap-4 mb-6">
          <div>
            <div className="text-[var(--color-text-muted)] text-sm mb-1">Current Streak</div>
            <div className="text-[22px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
              {habit.current_streak}
            </div>
          </div>
          <div>
            <div className="text-[var(--color-text-muted)] text-sm mb-1">Longest Streak</div>
            <div className="text-[22px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
              {habit.longest_streak}
            </div>
          </div>
          <div>
            <div className="text-[var(--color-text-muted)] text-sm mb-1">Total Completions</div>
            <div className="text-[22px] font-mono font-medium" style={{ fontVariantNumeric: 'tabular-nums' }}>
              {habit.completions?.length || 0}
            </div>
          </div>
        </div>

        <button
          onClick={handleToggleToday}
          disabled={toggleMutation.isPending}
          className={`w-full py-3 rounded-lg transition-colors font-medium ${
            habit.completed_today
              ? 'bg-[var(--color-success)] text-white hover:opacity-90'
              : 'bg-[var(--color-primary)] text-white hover:bg-[var(--color-primary-hover)]'
          } disabled:opacity-50`}
        >
          {toggleMutation.isPending
            ? 'Updating...'
            : habit.completed_today
            ? '✓ Completed Today'
            : 'Mark Today as Complete'}
        </button>
      </div>

      {habit.completions && habit.completions.length > 0 && (
        <div className="bg-[var(--color-surface)] rounded-xl p-6 border border-[var(--color-border)]">
          <h2 className="text-[18px] font-medium mb-4">Completion History</h2>
          <div className="flex flex-wrap gap-2">
            {habit.completions
              .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
              .slice(0, 30)
              .map((completion) => (
                <div
                  key={completion.id}
                  className={`px-3 py-1 rounded-full text-sm font-mono ${getColorClass(habit.color)} text-white`}
                  style={{ fontVariantNumeric: 'tabular-nums' }}
                >
                  {completion.date}
                </div>
              ))}
          </div>
        </div>
      )}
    </div>
  );
}

