import { useAuth } from '../contexts/AuthContext';

export function Layout({ children }: { children: React.ReactNode }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = React.useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-[var(--color-bg)]">
      <nav className="bg-[var(--color-surface)] border-b border-[var(--color-border)]">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-8">
              <Link to="/" className="text-[18px] font-medium">
                Ethara
              </Link>

              <div className="hidden md:flex gap-6">
                <Link to="/" className="text-sm hover:text-[var(--color-primary)] transition-colors">
                  Dashboard
                </Link>
                <Link to="/habits" className="text-sm hover:text-[var(--color-primary)] transition-colors">
                  Habits
                </Link>
              </div>
            </div>

            <div className="flex items-center gap-4">
              <div className="hidden md:flex items-center gap-4">
                {user && (
                  <>
                    <span className="text-sm text-[var(--color-text-muted)]">{user.email}</span>
                    <button
                      onClick={handleLogout}
                      className="text-sm hover:text-[var(--color-primary)] transition-colors"
                    >
                      Sign out
                    </button>
                  </>
                )}
              </div>

              <button
                className="md:hidden"
                onClick={() => setMenuOpen(!menuOpen)}
                aria-label="Toggle menu"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d={menuOpen ? 'M6 18L18 6M6 6l12 12' : 'M4 6h16M4 12h16M4 18h16'}
                  />
                </svg>
              </button>
            </div>
          </div>

          {menuOpen && (
            <div className="md:hidden border-t border-[var(--color-border)] py-4">
              <Link
                to="/"
                className="block py-2 hover:text-[var(--color-primary)] transition-colors"
                onClick={() => setMenuOpen(false)}
              >
                Dashboard
              </Link>
              <Link
                to="/habits"
                className="block py-2 hover:text-[var(--color-primary)] transition-colors"
                onClick={() => setMenuOpen(false)}
              >
                Habits
              </Link>
              {user && (
                <>
                  <div className="py-2 text-sm text-[var(--color-text-muted)]">{user.email}</div>
                  <button
                    onClick={() => {
                      handleLogout();
                      setMenuOpen(false);
                    }}
                    className="block py-2 hover:text-[var(--color-primary)] transition-colors"
                  >
                    Sign out
                  </button>
                </>
              )}
            </div>
          )}
        </div>
      </nav>

      <main>{children}</main>
    </div>
  );
}

