import type { AuthResponse, Habit, HabitDetail, Dashboard } from '../types';

class APIClient {
  private baseURL = '/api';
  private token: string | null = null;

  setToken(token: string | null) {
    this.token = token;
    if (token) {
      localStorage.setItem('auth_token', token);
    } else {
      localStorage.removeItem('auth_token');
    }
  }

  getToken(): string | null {
    if (!this.token) {
      this.token = localStorage.getItem('auth_token');
    }
    return this.token;
  }

  private async request<T>(
    path: string,
    options: RequestInit = {}
  ): Promise<T> {
    const token = this.getToken();
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      ...options.headers,
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const response = await fetch(`${this.baseURL}${path}`, {
      ...options,
      headers,
    });

    if (response.status === 401) {
      this.setToken(null);
      window.location.href = '/login';
      throw new Error('Unauthorized');
    }

    if (!response.ok) {
      const error = await response.json().catch(() => ({ error: 'Unknown error' }));
      throw new Error(error.message || error.error || 'Request failed');
    }

    if (response.status === 204) {
      return null as T;
    }

    return response.json();
  }

  async login(email: string, password: string): Promise<AuthResponse> {
    const response = await this.request<AuthResponse>('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    this.setToken(response.access_token);
    return response;
  }

  async logout() {
    this.setToken(null);
  }

  async getHabits(): Promise<Habit[]> {
    return this.request<Habit[]>('/habits');
  }

  async getHabit(id: string): Promise<HabitDetail> {
    return this.request<HabitDetail>(`/habits/${id}`);
  }

  async createHabit(data: {
    name: string;
    color: string;
    description?: string;
  }): Promise<Habit> {
    return this.request<Habit>('/habits', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async updateHabit(
    id: string,
    data: { name?: string; color?: string; description?: string }
  ): Promise<Habit> {
    return this.request<Habit>(`/habits/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  async deleteHabit(id: string): Promise<void> {
    return this.request<void>(`/habits/${id}`, {
      method: 'DELETE',
    });
  }

  async markComplete(habitId: string, date: string): Promise<void> {
    return this.request<void>(`/habits/${habitId}/complete`, {
      method: 'POST',
      body: JSON.stringify({ date }),
    });
  }

  async unmarkComplete(habitId: string, date: string): Promise<void> {
    return this.request<void>(`/habits/${habitId}/complete`, {
      method: 'DELETE',
      body: JSON.stringify({ date }),
    });
  }

  async getDashboard(): Promise<Dashboard> {
    return this.request<Dashboard>('/dashboard');
  }
}

