const PocketBase = require('pocketbase');
const fetch = require('node-fetch');

const PB_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = 'admin@ethara.local';
const ADMIN_PASSWORD = 'admin-setup-2026';

async function pbFetch(path, options = {}) {
  const response = await fetch(`${PB_URL}/api${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  return response;
}

async function setupCollections(token) {
  console.log('\nCreating habits collection...');

  try {
    const habitsRes = await pbFetch('/collections', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: { min: 1, max: 80 },
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: { max: 200 },
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'],
            },
          },
          {
            name: 'deleted',
            type: 'bool',
            required: true,
          },
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_user_name ON habits (user_id, LOWER(name)) WHERE deleted = FALSE',
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      }),
    });

    if (habitsRes.ok || (await habitsRes.text()).includes('already exists')) {
      console.log('✓ Habits collection created');
    }
  } catch (e) {
    console.log('Note: Habits collection may already exist');
  }

  console.log('\nCreating completions collection...');

  try {
    const completionsRes = await pbFetch('/collections', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        name: 'completions',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'habit_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: 'habits',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'date',
            type: 'text',
            required: true,
            options: {
              min: 10,
              max: 10,
              pattern: '^\\d{4}-\\d{2}-\\d{2}$',
            },
          },
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_completion ON completions (user_id, habit_id, date)',
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      }),
    });

    if (completionsRes.ok || (await completionsRes.text()).includes('already exists')) {
      console.log('✓ Completions collection created');
    }
  } catch (e) {
    console.log('Note: Completions collection may already exist');
  }
}

async function main() {
  console.log('===== Ethara Automated Setup =====\n');

  console.log('Testing PocketBase connection...');
  const healthRes = await pbFetch('/health');
  if (!healthRes.ok) {
    console.error('ERROR: PocketBase is not accessible');
    process.exit(1);
  }
  console.log('✓ PocketBase is accessible\n');

  // Try to authenticate with existing admin
  console.log('Attempting to authenticate as admin...');
  const authRes = await pbFetch('/admins/auth-with-password', {
    method: 'POST',
    body: JSON.stringify({
      identity: ADMIN_EMAIL,
      password: ADMIN_PASSWORD,
    }),
  });

  let token;

  if (authRes.ok) {
    const authData = await authRes.json();
    token = authData.token;
    console.log('✓ Admin authentication successful\n');
  } else {
    console.log('\n⚠️  Admin authentication failed');
    console.log('\nMANUAL SETUP REQUIRED:');
    console.log('1. Open http://pocketbase:8090/_/ in your browser');
    console.log('2. Create an admin account with:');
    console.log(`   Email: ${ADMIN_EMAIL}`);
    console.log(`   Password: ${ADMIN_PASSWORD}`);
    console.log('3. Run this script again\n');
    process.exit(1);
  }

  await setupCollections(token);

  console.log('\n✓ Collections setup complete!\n');
  console.log('Running seed script...\n');

  const { execSync } = require('child_process');
  execSync('node seed-data.js', { stdio: 'inherit', cwd: __dirname });

  console.log('\n===== Setup Complete! =====\n');
}

main().catch(console.error);

