#!/usr/bin/env node

const fetch = require('/app/backend/node_modules/node-fetch');
const { execSync } = require('child_process');

const PB_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = 'admin@ethara.local';
const ADMIN_PASSWORD = 'admin-setup-2026';

async function pbFetch(path, options = {}) {
  const response = await fetch(`${PB_URL}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  return response;
}

async function checkHealth() {
  try {
    const res = await pbFetch('/api/health');
    return res.ok;
  } catch (e) {
    return false;
  }
}

async function getAdminToken() {
  try {
    const res = await pbFetch('/api/admins/auth-with-password', {
      method: 'POST',
      body: JSON.stringify({
        identity: ADMIN_EMAIL,
        password: ADMIN_PASSWORD,
      }),
    });

    if (res.ok) {
      const data = await res.json();
      return data.token;
    }
  } catch (e) {
    // Ignore
  }
  return null;
}

async function tryCreateAdmin() {
  // Try various endpoints that might allow admin creation
  const endpoints = [
    '/api/setup',
    '/api/admins',
    '/api/admins/create',
    '/api/install',
  ];

  for (const endpoint of endpoints) {
    try {
      const res = await pbFetch(endpoint, {
        method: 'POST',
        body: JSON.stringify({
          email: ADMIN_EMAIL,
          password: ADMIN_PASSWORD,
          passwordConfirm: ADMIN_PASSWORD,
        }),
      });

      if (res.ok) {
        return true;
      }
    } catch (e) {
      // Continue trying
    }
  }

  return false;
}

async function createCollections(token) {
  console.log('\n📦 Creating PocketBase collections...\n');

  try {
    // Create habits collection
    const habitsRes = await pbFetch('/api/collections', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: { min: 1, max: 80 },
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: { max: 200 },
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'],
            },
          },
          {
            name: 'deleted',
            type: 'bool',
            required: true,
          },
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_user_name ON habits (user_id, LOWER(name)) WHERE deleted = FALSE',
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      }),
    });

    if (habitsRes.ok) {
      console.log('✓ Created habits collection');
    } else {
      const error = await habitsRes.text();
      if (error.includes('already exists')) {
        console.log('✓ Habits collection already exists');
      } else {
        console.log('⚠️  Warning: Could not create habits collection:', error.substring(0, 100));
      }
    }

    // Create completions collection
    const completionsRes = await pbFetch('/api/collections', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}` },
      body: JSON.stringify({
        name: 'completions',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'habit_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: 'habits',
              cascadeDelete: false,
              maxSelect: 1,
            },
          },
          {
            name: 'date',
            type: 'text',
            required: true,
            options: {
              min: 10,
              max: 10,
              pattern: '^\\d{4}-\\d{2}-\\d{2}$',
            },
          },
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_completion ON completions (user_id, habit_id, date)',
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      }),
    });

    if (completionsRes.ok) {
      console.log('✓ Created completions collection');
    } else {
      const error = await completionsRes.text();
      if (error.includes('already exists')) {
        console.log('✓ Completions collection already exists');
      } else {
        console.log('⚠️  Warning: Could not create completions collection:', error.substring(0, 100));
      }
    }

    return true;
  } catch (e) {
    console.error('Error creating collections:', e.message);
    return false;
  }
}

async function seedData() {
  console.log('\n🌱 Seeding data...\n');
  try {
    execSync('node seed-data.js', { cwd: '/app/backend', stdio: 'inherit' });
    return true;
  } catch (e) {
    console.error('Error seeding data:', e.message);
    return false;
  }
}

async function main() {
  console.log('╔════════════════════════════════════════╗');
  console.log('║   Ethara Complete Setup Script        ║');
  console.log('╚════════════════════════════════════════╝\n');

  // Step 1: Check PocketBase connectivity
  console.log('1️⃣  Checking PocketBase connectivity...');
  const isHealthy = await checkHealth();
  if (!isHealthy) {
    console.error('❌ PocketBase is not accessible at', PB_URL);
    console.log('\nPlease ensure PocketBase is running and accessible.');
    process.exit(1);
  }
  console.log('✓ PocketBase is accessible\n');

  // Step 2: Try to get or create admin
  console.log('2️⃣  Setting up PocketBase admin...');
  let token = await getAdminToken();

  if (token) {
    console.log('✓ Admin account exists and is accessible\n');
  } else {
    console.log('Admin not found, attempting to create...');
    const created = await tryCreateAdmin();

    if (created) {
      console.log('✓ Admin created successfully');
      token = await getAdminToken();
    } else {
      console.log('\n⚠️  Could not create admin automatically\n');
      console.log('╔════════════════════════════════════════════════════════════╗');
      console.log('║  MANUAL SETUP REQUIRED                                     ║');
      console.log('╠════════════════════════════════════════════════════════════╣');
      console.log('║                                                            ║');
      console.log('║  1. Open http://pocketbase:8090/_/ in a browser           ║');
      console.log('║  2. Create an admin account:                               ║');
      console.log('║     Email: admin@ethara.local                              ║');
      console.log('║     Password: admin-setup-2026                             ║');
      console.log('║  3. Run this script again: node complete-setup.js          ║');
      console.log('║                                                            ║');
      console.log('╚════════════════════════════════════════════════════════════╝\n');
      process.exit(1);
    }
  }

  // Step 3: Create collections
  console.log('3️⃣  Setting up collections...');
  if (!token) {
    console.log('❌ No admin token available');
    process.exit(1);
  }

  await createCollections(token);

  // Step 4: Seed data
  console.log('\n4️⃣  Seeding database...');
  await seedData();

  console.log('\n╔════════════════════════════════════════════════════════════╗');
  console.log('║  ✅ SETUP COMPLETE!                                         ║');
  console.log('╠════════════════════════════════════════════════════════════╣');
  console.log('║                                                            ║');
  console.log('║  🌐 Application: http://0.0.0.0:4173                       ║');
  console.log('║                                                            ║');
  console.log('║  📧 Demo Account:                                          ║');
  console.log('║     Email: demo@ethara.ai                                  ║');
  console.log('║     Password: deku-demo-pw-2026                            ║');
  console.log('║                                                            ║');
  console.log('╚════════════════════════════════════════════════════════════╝\n');
}

main().catch((err) => {
  console.error('\n❌ Fatal error:', err.message);
  process.exit(1);
});

