const ADMIN_EMAIL = 'admin@ethara.local';
const ADMIN_PASSWORD = 'admin-setup-2026';

async function pbFetch(path, options = {}) {
  const response = await fetch(`${PB_URL}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  return response;
}

async function checkHealth() {
  try {
    const res = await pbFetch('/api/health');
    return res.ok;
  } catch (e) {
    return false;
  }
}

async function getAdminToken() {
  try {
    const res = await pbFetch('/api/admins/auth-with-password', {
      method: 'POST',
      body: JSON.stringify({
        identity: ADMIN_EMAIL,
        password: ADMIN_PASSWORD,
      }),
    });

    if (res.ok) {
      const data = await res.json();
      return data.token;
    }
  } catch (e) {
    // Ignore
  }
  return null;
}

async function tryCreateAdmin() {
  // Try various endpoints that might allow admin creation
  const endpoints = [
    '/api/setup',
    '/api/admins',
    '/api/admins/create',
    '/api/install',
  ];

  for (const endpoint of endpoints) {
    try {
      const res = await pbFetch(endpoint, {
        method: 'POST',
        body: JSON.stringify({
          email: ADMIN_EMAIL,
          password: ADMIN_PASSWORD,
          passwordConfirm: ADMIN_PASSWORD,
        }),
      });

      if (res.ok) {
        return true;
      }
    } catch (e) {
